const $=s=>document.querySelector(s), samples=window.SUAP_SAMPLES;
const course=[{id:'m1',num:'01',name:'Arquitetura e fluxo web',desc:'Entenda como o SUAP conecta URLs, views, models, forms e templates.',goals:['Reconhecer a estrutura do módulo EDU','Seguir o caminho de uma requisição','Identificar métodos e relacionamentos do model Turma','Montar uma tela simples conectando URL, view protegida e template','Investigar e atender chamados simples de alteração de interface'],tasks:['Localize a rota da página de turma em edu/urls.py.','Localize a view turma() e identifique o parâmetro pk.','Encontre os managers objects e locals no model Turma.','Explique de onde vêm alunos, diários e horários da turma.','Localize o bloco de relatórios em edu/urls.py e identifique onde a nova rota seria inserida.','Examine relatorio_horario em edu/views.py e registre quais elementos podem orientar uma nova view.','Explique como @rtr, @permission_required e return locals() participam da tela de treinamento.','Em um ambiente isolado, crie o template proposto e confirme que título, links e total de links são exibidos.'],quiz:[['Qual componente decide qual view atenderá uma URL?',['Model','urls.py','Template'],1,'O arquivo de rotas mapeia o caminho solicitado para uma view.'],['Qual método da view procura a turma e retorna 404 se não a encontrar?',['get_object_or_404','get_horarios','locals'],0,'get_object_or_404 consulta o manager informado e responde com 404 quando não encontra o objeto.'],['Quem entrega o contexto ao template no fluxo MTV?',['Model diretamente','Banco de dados','View, com ajuda do mecanismo de renderização'],2,'A view prepara os dados; o decorator @rtr do SUAP pode transformar o dicionário retornado em resposta renderizada.'],['Na nova tela, qual elemento protege o acesso no servidor?',['A classe CSS do botão','@permission_required','O laço for do template'],1,'@permission_required verifica a autorização antes da execução da view; controles visuais do template não substituem essa proteção.']]},{id:'m2',num:'02',name:'Decorators e geração de PDF',desc:'Descubra como @rtr, @documento, httprr e PDFResponse participam das respostas.',goals:['Entender o papel de um decorator','Explicar o retorno locals() da view turma()','Distinguir redirecionamento e resposta PDF'],tasks:['Localize a função rtr() em djtools/utils/response.py.','Identifique o teste isinstance(f_return, HttpResponse).','Encontre get_template_path() e explique a convenção de nomes.','Examine httprr() e PDFResponse e registre suas diferenças.'],quiz:[['O que @rtr faz quando a view retorna um dicionário?',['Renderiza um template usando o retorno como contexto','Exclui os dados','Cria uma migration'],0,'A implementação chama render() quando o retorno não é um HttpResponse.'],['O que acontece se a view já retornar HttpResponse?',['É renderizado novamente','@rtr devolve a resposta diretamente','O usuário recebe erro 404'],1,'O decorator verifica isinstance(f_return, HttpResponse) e retorna o resultado sem renderização adicional.'],['Qual resposta é própria para conteúdo PDF no trecho fornecido?',['HttpRequest','PDFResponse','get_template_path'],1,'PDFResponse define content_type application/pdf e Content-Disposition.']]},{id:'m3',num:'03',name:'Grupos e permissões',desc:'Entenda como papéis, YAML, permissões e verificações contextuais se relacionam.',goals:['Distinguir grupo, permissão e regra contextual','Compreender a função de permissions.yaml','Investigar uma autorização no módulo EDU'],tasks:['Localize um grupo acadêmico em permissions.yaml.','Identifique uma checagem has_group_cached na view turma().','Localize perms.realizar_procedimentos_academicos e descreva seus parâmetros.','Explique por que ocultar um botão no template não substitui a autorização na view.'],quiz:[['Onde o SUAP declara permissões de grupos, conforme o roteiro?',['permissions.yaml','models.py apenas','templates/ apenas'],0,'O YAML associa grupos e permissões, que precisam ser sincronizadas no sistema.'],['A variável pode_realizar_procedimentos considera:',['Apenas a URL','Usuário e curso da turma','Apenas o nome do template'],1,'A view chama perms.realizar_procedimentos_academicos(request.user, obj.curso_campus).'],['Ocultar uma ação no template é suficiente para impedir seu uso?',['Sim','Somente com JavaScript','Não, a operação precisa verificar autorização no servidor'],2,'O controle visual melhora a interface, mas não substitui a autorização no backend.']]}];
const module2Course=course.find(m=>m.id==='m2');
module2Course.desc='Compreenda como os decorators controlam autenticação, autorização, renderização, transações e geração de documentos no SUAP.';
module2Course.goals=['Explicar a ordem de aplicação e execução dos decorators','Distinguir @login_required, @permission_required e @group_required','Compreender @rtr, @documento e seus principais parâmetros','Reconhecer os cuidados de @transaction.atomic e @csrf_exempt','Montar e testar um PDF autenticável com dados gerais do aluno'];
module2Course.tasks=['Localize a função rtr() em djtools/utils/response.py.','Identifique o teste isinstance(f_return, HttpResponse).','Encontre get_template_path() e explique a convenção de nomes.','Examine httprr() e PDFResponse e registre suas diferenças.','Compare @login_required, @permission_required e @group_required e registre quando utilizar cada um.','Localize a implementação de @documento e identifique os efeitos de landscape, enumerar_paginas, validade e modelo.','Explique o que muda quando @documento recebe um primeiro parâmetro textual.','Localize exemplos de @transaction.atomic, @csrf_exempt e @documentos.emissao_documentos() nas referências indicadas.','Crie a URL e o botão do exemplo Dados Gerais do Aluno em um ambiente isolado.','Implemente a view e o template PDF do exemplo, substituindo permissões fixas por regras adequadas antes de qualquer uso real.','Teste o PDF, o código de autenticação e a visualização HTML com ?html=1.'];
module2Course.quiz=[['O que @rtr faz quando a view retorna um dicionário?',['Renderiza um template usando o retorno como contexto','Exclui os dados','Cria uma migration'],0,'A implementação chama render() quando o retorno não é um HttpResponse.'],['O que acontece se a view já retornar HttpResponse?',['É renderizado novamente','@rtr devolve a resposta diretamente','O usuário recebe erro 404'],1,'O decorator verifica isinstance(f_return, HttpResponse) e retorna o resultado sem renderização adicional.'],['Qual resposta é própria para conteúdo PDF no trecho fornecido?',['HttpRequest','PDFResponse','get_template_path'],1,'PDFResponse define content_type application/pdf e Content-Disposition.'],['Qual decorator transforma o HTML renderizado em documento PDF?',['@rtr','@documento','@login_required'],1,'@rtr prepara o HTML; @documento converte esse resultado em PDF/documento.'],['Em uma lista de permissões, qual é a lógica padrão de @permission_required?',['and','or','xor'],1,'Por padrão, possuir uma das permissões é suficiente. Use logic_operator="and" quando todas forem obrigatórias.'],['O que acontece quando @documento recebe um primeiro parâmetro textual?',['O template deixa de ser usado','O documento ganha tipo de verificação e pode receber código de autenticação','A view fica pública'],1,'O texto define tipo_para_verificacao, permitindo registrar e autenticar o documento.'],['Qual cuidado é obrigatório no exemplo Dados Gerais do Aluno?',['Manter is_admin=True em produção','Remover todos os decorators','Substituir permissões fixas pelas regras contextuais reais'],2,'Os valores True existem apenas para a demonstração. Uma demanda real deve reaproveitar as regras de autorização da tela do aluno.']];
const module3Course=course.find(m=>m.id==='m3');
module3Course.desc='Acompanhe grupos, YAML, sincronização e checagens; investigue regras contextuais e três chamados reais do EDU.';
module3Course.goals.push('Explicar o fluxo permissions.yaml → sync_permissions → banco → checagem','Localizar verificações em views, templates, menus, decorators e managers','Comparar os chamados 1144, 1168 e 1157','Validar alterações de permissão e restaurar o ambiente de treinamento');
module3Course.tasks.push('Leia a declaração Administrador Acadêmico e identifique grupo, app, modelo e codename.','Localize sync_permissions e sync_groups_and_permissions e confirme como adicionam e removem associações.','Registre exemplos das cinco camadas de checagem com arquivo e linha.','Aplique o checklist de investigação a uma demanda e registre evidências e dados sensíveis envolvidos.','Em ambiente isolado, teste a alteração de view_aluno e restaure o estado inicial; registre as permissões efetivas.','Em ambiente isolado, teste add_aluno no botão e na URL direta do admin; restaure e registre o resultado.','Analise a issue 1144 e o merge 400d69076d; registre o alcance das três permissões de aluno.','Analise a issue 1168 e o merge 051aed03cd; siga perms.py → view → template ENADE.','Analise a issue 1157 e o merge 6fae1e80a6; confira as views de destino dos documentos.');
module3Course.quiz.push(['As telas consultam diretamente o YAML em cada acesso?',['Sim','Não: a sincronização alimenta as associações no banco','Somente os templates'],1,'O YAML declara permissões; a aplicação verifica as associações sincronizadas e as regras contextuais.'],['Quando a condição com três has_perm negados ligados por and deixa de bloquear?',['Quando ao menos uma permissão aceita está presente','Somente quando todas estão presentes','Quando o menu aparece'],0,'Basta uma das permissões para essa condição não bloquear; outras regras ainda podem restringir o acesso.'],['Qual camada mudou no chamado 1168?',['Apenas o menu','Uma regra contextual em edu/perms.py','O CSS'],1,'O grupo Secretário Acadêmico foi incluído na regra ENADE, consumida pela view e pelo template.'],['Remover view_aluno de um grupo garante a perda do acesso?',['Sempre','Não: confira sincronização, outros grupos e permissões diretas','Sim, se o botão sumiu'],1,'Confirme a revogação no banco e a ausência de outras fontes de permissão antes de avaliar a checagem.'],['O trecho do chamado 1157 comprova bloqueio de documentos no servidor?',['Sim','Não: é preciso conferir as views de destino','Sim, porque altera o template'],1,'O trecho controla apresentação. Ocultar Documentos não substitui a autorização na view.']);
const moduleChallenges={m1:[{id:'pesquisa-aluno-titulo',title:'Título da pesquisa de aluno',area:'Administração acadêmica',url:'https://suap.ifg.edu.br/admin/edu/aluno/',request:'A equipe da Secretaria Acadêmica solicita que o título exibido na página de pesquisa de alunos seja alterado para “Pesquisa de Aluno”.',acceptance:'Ao acessar a pesquisa de alunos, a página deve apresentar o novo título sem alterar os filtros ou os resultados.'},{id:'pesquisa-aluno-botao',title:'Texto do botão de pesquisa',area:'Administração acadêmica',url:'https://suap.ifg.edu.br/admin/edu/aluno/',request:'Na mesma tela de pesquisa de alunos, altere o texto do botão responsável por iniciar a consulta para “Pesquisar”.',acceptance:'O botão deve exibir “Pesquisar” e continuar executando a busca normalmente.'},{id:'aluno-periodo-ingresso',title:'Rótulo do período de ingresso',area:'Detalhamento do aluno',url:'https://suap.ifg.edu.br/edu/aluno/id_matricula/',request:'No detalhamento do aluno, substitua o texto “Ingresso” por “Período de Ingresso”.',acceptance:'O novo rótulo deve aparecer no detalhamento sem modificar o valor ou os demais dados acadêmicos.'},{id:'aluno-periodo-ingresso-duplicado',title:'Rótulo do período de ingresso',area:'Detalhamento do aluno · possível duplicidade',url:'https://suap.ifg.edu.br/edu/aluno/id_matricula/',request:'No detalhamento do aluno, substitua o texto “Ingresso” por “Período de Ingresso”.',acceptance:'Antes de implementar, compare este pedido com os chamados em aberto, identifique a possível duplicidade e registre a decisão de atendimento.',duplicate:true}]};
moduleChallenges.m2=[{id:'restringir-relatorio-permissao',title:'Restringir relatório por permissão',area:'Autorização · @permission_required',url:'/edu/relatorio_horario/',request:'A página do relatório está disponível para qualquer usuário autenticado. Altere a proteção da view para exigir a permissão edu.gerar_relatorio.',acceptance:'Um usuário com a permissão acessa o relatório normalmente; um usuário sem a permissão recebe acesso negado pelo servidor.'},{id:'restringir-tela-grupo',title:'Restringir tela por grupo',area:'Autorização · @group_required',url:'edu/views.py · view acadêmica indicada no exercício',request:'Restrinja a funcionalidade acadêmica aos grupos Administrador Acadêmico, Diretor Acadêmico e Secretário Acadêmico.',acceptance:'Somente usuários pertencentes a pelo menos um dos grupos informados conseguem executar a view.'},{id:'ajustar-pdf-paisagem',title:'Ajustar orientação e paginação de PDF',area:'Documento · @documento',url:'edu/views.py · relatório PDF indicado no exercício',request:'O relatório possui muitas colunas e está difícil de ler. Gere o documento em modo paisagem e remova a numeração das páginas.',acceptance:'O PDF é gerado com landscape=True e enumerar_paginas=False, sem perder informações do relatório.'},{id:'declaracao-autenticavel',title:'Tornar declaração autenticável',area:'Documento · código verificador',url:'/comum/autenticar_documento/',request:'Uma declaração atualmente gera um PDF simples. Configure-a com validade de 30 dias e código de autenticação para que possa ser verificada no SUAP.',acceptance:'O PDF apresenta código de autenticação, o documento é registrado e sua verificação pode ser realizada na área de autenticação.'},{id:'corrigir-dados-pessoais-pdf',title:'Corrigir exposição de dados pessoais no PDF',area:'Segurança · regras contextuais',url:'/edu/dados_gerais_aluno_pdf/<pk>/',request:'O PDF de dados gerais utiliza permissões fixas, como pode_ver_cpf = True. Substitua esses valores pelas regras contextuais aplicadas na tela do aluno.',acceptance:'CPF e demais dados sensíveis aparecem somente para usuários autorizados; para os demais, as informações permanecem ocultas ou mascaradas.'}];
let state={};try{state=JSON.parse(localStorage.getItem('suapEduParticipanteV1')||'{}')}catch{};const save=()=>localStorage.setItem('suapEduParticipanteV1',JSON.stringify(state));const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const taskDone=m=>m.tasks.filter((t,i)=>state['task:'+m.id+':'+i]).length;const challengeDone=m=>(moduleChallenges[m.id]||[]).filter(c=>state['ticket:'+m.id+':'+c.id]).length;const moduleTotal=m=>m.tasks.length+(moduleChallenges[m.id]||[]).length;const moduleDone=m=>taskDone(m)+challengeDone(m);const modulePercent=m=>Math.round(moduleDone(m)/moduleTotal(m)*100);const card=m=>`<section class="modulecard"><span class="tag">MÓDULO ${m.num} · DISPONÍVEL</span><h3>${m.name}</h3><p>${m.desc}</p><div class="bar"><div style="width:${modulePercent(m)}%"></div></div><span class="muted small">${moduleDone(m)}/${moduleTotal(m)} atividades realizadas</span><button class="btn" data-page="${m.id}">Estudar módulo →</button></section>`;
function home(){return `<div class="hero"><span class="eyebrow">TRILHA DE APRENDIZAGEM · SUAP EDU</span><h1>Introdução ao Desenvolvimento SUAP</h1><p>Um guia de estudos com exemplos reais de código, exercícios práticos e explicações para consultar durante e depois das aulas.</p><button class="btn" data-page="m1">Começar pelo módulo 01 →</button></div><div class="stats"><div class="stat"><strong>10 h</strong><span>5 encontros planejados</span></div><div class="stat"><strong>03</strong><span>Módulos de estudo disponíveis</span></div><div class="stat"><strong>${course.reduce((n,m)=>n+moduleDone(m),0)}/${course.reduce((n,m)=>n+moduleTotal(m),0)}</strong><span>Atividades realizadas</span></div></div><section class="panel"><span class="tag">ENTENDA A ARQUITETURA</span><h2>Do endereço à página: o fluxo MTV</h2><p class="muted">A view recebe a requisição encaminhada pelas URLs, consulta os models e prepara o contexto utilizado pelo template.</p><img class="diagram" src="fluxo_django_mtv.png" alt="Diagrama do fluxo: usuário, URL, view, model, banco de dados, template e resposta HTML"><p class="small muted">Diagrama introdutório. O processamento real também pode retornar JSON, PDF ou redirecionamentos.</p></section><h2>Seus módulos de estudo</h2><div class="grid3">${course.map(card).join('')}</div><section class="panel"><h2>Como estudar com este guia</h2><div class="grid3"><div><h3>01 · Compreenda</h3><p>Leia os conceitos e examine as relações entre os componentes.</p></div><div><h3>02 · Investigue</h3><p>Abra os arquivos indicados no VSCode e localize as implementações.</p></div><div><h3>03 · Pratique</h3><p>Conclua as atividades, responda às questões e registre suas descobertas.</p></div></div></section><div class="tip">Os encontros 4 e 5 já aparecem no plano de curso, mas ainda não têm material de estudo completo nesta versão.</div>`}
const row=(a,b)=>`<tr><th>${a}</th><td>${b}</td></tr>`;
function plan(){return `<div class="sectionhead"><span class="eyebrow">ORIENTAÇÃO DO CURSO</span><h1>Plano de curso</h1><p>Desenvolvimento SUAP com foco no EDU · 10 horas · 5 encontros de 2 horas</p></div><div class="panel"><h2>Por que este curso?</h2><p>O SUAP é um projeto Django modular com componentes próprios. O módulo <code>edu</code> reúne regras acadêmicas, cadastros, diários, horários, históricos, documentos e permissões. Aqui você aprenderá a localizar e compreender implementações reais antes de propor alterações.</p><h3>Objetivo geral</h3><p>Desenvolver autonomia para localizar funcionalidades, compreender fluxos web, investigar chamados, alterar regras de negócio e validar correções no SUAP.</p><h3>O que você deverá conseguir fazer</h3><ul><li>Reconhecer a organização do projeto e do módulo EDU.</li><li>Seguir uma URL até a view, o model, o form e o template.</li><li>Compreender managers, consultas ORM e permissões contextuais.</li><li>Investigar erros usando evidências e propor correções seguras.</li><li>Criar ou adaptar testes de regressão.</li></ul></div><div class="panel"><h2>Os cinco encontros</h2><div class="tablewrap"><table><thead><tr><th>Encontro</th><th>Conteúdo</th><th>Caso principal</th><th>Atividade</th></tr></thead><tbody>${[['01','Arquitetura e localização','Horários de turma/aluno','Exploração'],['02','URLs, views, templates e forms','Definição e exibição de horários','Exploração'],['03','Models, ORM, admin e permissões','Secretaria Acadêmica e relações acadêmicas','Exploração/diagnóstico'],['04','Debugging e investigação','Pendências por Diretoria','Diagnóstico'],['05','Implementação, testes e entrega','Diário pendente, PCC e nao_exige_nota','Implementação']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="grid2"><section class="panel"><h2>Metodologia</h2><p><strong>Conhecer → Localizar → Compreender → Investigar → Corrigir → Validar.</strong></p><p>As atividades são de exploração, diagnóstico e implementação em ambiente isolado.</p></section><section class="panel"><h2>Avaliação</h2><p>Participação nas investigações, entregáveis, referências a arquivos e linhas, clareza na identificação de causas e qualidade das propostas de teste.</p></section></div><div class="panel"><h2>Versões e referências</h2><p>O repositório analisado utiliza Django 4.1.5, DRF 3.14.0, Celery 5.2.7 e behave 1.2.6. O ambiente de desenvolvimento documentado usa PostgreSQL.</p><p>Commit de referência: <code>936e818c17</code>. Linhas verificadas em 11/10/2026; podem variar conforme a versão do repositório.</p><a href="plano_curso.md" download>Baixar o plano completo em Markdown ↓</a></div>`}
function code(key,title,desc){const x=samples[key];return `<section class="codepanel"><h3>${title}</h3><p>${desc}</p><div class="fileline">${escape(x.file)} ${x.line?`· linhas ${x.line}–${x.end} do arquivo fornecido`:''}</div><div class="codebar"><span class="tag">CÓDIGO REAL · ${key==='view'?'VIEW COMENTADA':'FONTE ANEXADA'}</span><div class="buttons"><button data-copy="${key}">Copiar</button><button data-toggle="${key}">Ocultar comentários</button></div></div><div class="codebox" id="code-${key}">${x.code.split('\n').map((l,i)=>`<span class="line ${l.trim().startsWith('#')?'comment':''}"><span class="ln">${x.line?x.line+i:i+1}</span>${escape(l)||' '}</span>`).join('')}</div></section>`}
