const studentPdfView=`@login_required
@documento('Dados Gerais do Aluno', validade=30, enumerar_paginas=False, modelo='edu.aluno')
@rtr('dados_gerais_aluno_pdf.html')
def dados_gerais_aluno_pdf(request, pk):
    obj = get_object_or_404(Aluno, pk=pk)
    title = f'Dados Gerais - {obj.get_nome()} ({obj.matricula})'

    # Exemplo didatico do treinamento: a tela exige apenas usuario logado.
    # Em uma demanda real, replique aqui as regras contextuais da view aluno.
    is_admin = True
    pode_ver_cpf = True
    pode_ver_dados_sociais = True
    pode_ver_dados_academicos = True

    diploma = RegistroEmissaoDiploma.objects.filter(aluno=obj, cancelado=False).order_by('-via')
    emitiu_diploma = diploma.exists()
    situacao_sistemica = obj.get_situacao_sistemica()
    qtd_periodos = obj.matriz.qtd_periodos_letivos if obj.matriz else '-'
    uo = obj.curso_campus.diretoria.setor.uo

    return locals()`;
const studentPdfTemplate=`{% extends "relatorio_pdf.html" %}

{% block style %}
    h1 {
        text-align: center;
        border: 1px solid #222;
        padding: 6px;
        font-size: 16pt;
    }

    .dados-gerais {
        width: 100%;
        border-collapse: collapse;
        margin-top: 12px;
    }

    .dados-gerais th {
        width: 24%;
        background: #f2f2f2;
        color: #333;
        border: 1px solid #ccc;
        padding: 6px;
        text-align: left;
        font-weight: bold;
    }

    .dados-gerais td {
        border: 1px solid #ccc;
        padding: 6px;
        text-align: left;
    }

    .foto {
        width: 95px;
        text-align: center;
    }

    .foto img {
        max-width: 75px;
        max-height: 100px;
    }

    .status-ok {
        background: #dff0d8;
        border-left: 4px solid #3c763d;
        padding: 3px 6px;
    }

    .status-alerta {
        background: #fcf8e3;
        border-left: 4px solid #8a6d3b;
        padding: 3px 6px;
    }

    .status-erro {
        background: #f2dede;
        border-left: 4px solid #a94442;
        padding: 3px 6px;
    }

    .observacao {
        font-size: 8pt;
        color: #555;
        line-height: 1.35em;
    }
{% endblock %}

{% block content %}

    <div class="corpo">
        <h1>Dados Gerais do Aluno</h1>

        <table class="dados-gerais">
            <tbody>
                <tr>
                    <td class="foto" rowspan="5">
                        <img src="{{ obj.get_foto_75x100_url }}" alt="Foto de {{ obj.get_nome }}">
                    </td>
                    <th>Nome</th>
                    <td>{{ obj.get_nome|normalizar }}</td>
                    <th>Matrícula</th>
                    <td>{{ obj.matricula }}</td>
                </tr>
                <tr>
                    <th>Ingresso</th>
                    <td>{{ obj.ano_letivo|format }}/{{ obj.periodo_letivo|format }}</td>
                    <th>E-mail Acadêmico</th>
                    <td>{{ obj.email_academico|format }}</td>
                </tr>
                <tr>
                    <th>E-mail Google Sala de Aula</th>
                    <td colspan="3">{{ obj.email_google_classroom|format }}</td>
                </tr>
                <tr>
                    <td colspan="4" class="observacao">
                        O login para este e-mail, e para os recursos do Google for Education,
                        e realizado exclusivamente atraves do link para o Google Sala de Aula
                        localizado no rodape de todas as paginas do SUAP. O login atraves de
                        senha nao esta habilitado para os servicos do Google for Education.
                    </td>
                </tr>
                <tr>
                    <th>CPF</th>
                    <td>{% if pode_ver_cpf %}{{ obj.pessoa_fisica.cpf|format }}{% else %}***.****.***-**{% endif %}</td>
                    <th>Período de Referência</th>
                    <td>{{ obj.periodo_atual|format }}º</td>
                </tr>
                <tr>
                    <th>I.R.A.</th>
                    <td>{% if pode_ver_dados_sociais or pode_ver_dados_academicos %}{{ obj.get_ira|format }}{% else %}**{% endif %}</td>
                    <th>Curso</th>
                    <td colspan="3">
                        {{ obj.curso_campus }}
                        {% if obj.habilitacao %} - Habilitação em {{ obj.habilitacao|format }}{% endif %}
                    </td>
                </tr>
                <tr>
                    <th>Matriz</th>
                    <td colspan="2">{{ obj.matriz|format }}</td>
                    <th>Qtd. Períodos</th>
                    <td>{{ qtd_periodos|format }}</td>
                </tr>
                <tr>
                    <th>Situação Sistêmica</th>
                    <td>
                        <span class="{% if situacao_sistemica.0 == 1 %}status-erro{% elif situacao_sistemica.0 == 2 %}status-alerta{% else %}status-ok{% endif %}">
                            {{ situacao_sistemica.1 }}
                        </span>
                    </td>
                    <th>Data da Migração</th>
                    <td colspan="2">{{ obj.data_integralizacao|format }}</td>
                </tr>
                <tr>
                    <th>Impressão Digital</th>
                    <td>{{ obj.pessoa_fisica.tem_digital|format }}</td>
                    <th>Chave Primária</th>
                    <td colspan="2">{% if is_admin %}{{ obj.pk }}{% else %}-{% endif %}</td>
                </tr>
                <tr>
                    <th>Emitiu Diploma</th>
                    <td>{{ emitiu_diploma|format }}</td>
                    <th>Campus</th>
                    <td colspan="2">{{ uo|format }}</td>
                </tr>
            </tbody>
        </table>
    </div>

{% endblock %}`;
const newScreenRoute="path('treinamento_fluxo_web/', views.treinamento_fluxo_web),";
const newScreenView=`@rtr('treinamento_fluxo_web.html')
@permission_required('edu.view_horarioauladiario')
def treinamento_fluxo_web(request):
    title = 'Treinamento - Fluxo Web EDU'
    links = [
        ('Listagem de Horarios', '/edu/relatorio_horario/'),
        ('Locais e Horarios do Aluno', '/edu/locais_aula_aluno/'),
        ('Locais e Horarios do Professor', '/edu/locais_aula_professor/'),
    ]
    return locals()`;
const newScreenTemplate=`{% extends super_template %}

{% block content %}
    {% box 'Fluxo URL, view e template' %}
        <p>
            Esta tela foi criada para demonstrar como uma URL chama uma view e
            como a view entrega dados para o template.
        </p>
    {% endbox %}

    {% box 'Links de navegacao' %}
        <ul class="action-bar">
            {% for label, url in links %}
                <li>
                    <a class="btn default" href="{{ url }}">{{ label }}</a>
                </li>
            {% endfor %}
        </ul>
    {% endbox %}

    {% box 'Dados recebidos da view' %}
        <table class="info">
            <tbody>
                <tr>
                    <td>Título</td>
                    <td>{{ title }}</td>
                </tr>
                <tr>
                    <td>Total de links</td>
                    <td>{{ links|length }}</td>
                </tr>
            </tbody>
        </table>
    {% endbox %}
{% endblock %}`;
function newScreenLesson(){return `<section class="lesson"><span class="tag">PRÁTICA GUIADA · URL → VIEW → TEMPLATE</span><h2>6. Crie uma tela simples no SUAP</h2><p>Nesta prática, você conectará uma nova rota a uma view protegida e apresentará os dados em um template. Realize as alterações somente em um ambiente de desenvolvimento isolado e confira as linhas no seu checkout antes de editar.</p><h3>Passo 1 · Defina a rota</h3><p>Abra <code>edu/urls.py</code> e localize o bloco de relatórios e atalhos indicado nas linhas 130–141 do checkout de referência. Após reconhecer o padrão das rotas próximas, insira a rota abaixo na posição correspondente à linha 135.</p><div class="fileline">edu/urls.py · referência: linhas 130–141</div><pre class="codebox" style="padding:18px"><code>${escape(newScreenRoute)}</code></pre><p>Essa declaração associa o endereço <code>/edu/treinamento_fluxo_web/</code> à função <code>treinamento_fluxo_web</code> de <code>edu/views.py</code>.</p><h3>Passo 2 · Examine uma view existente</h3><p>Antes de escrever a nova função, localize <code>relatorio_horario</code> em <code>edu/views.py</code>, nas linhas 6330–6338 do checkout de referência. Observe como essa view define <code>title</code>, instancia um formulário, processa os dados recebidos e retorna <code>locals()</code>. Use esse comportamento real como referência para reconhecer as convenções do módulo.</p><h3>Passo 3 · Crie a view de treinamento</h3><p>Adicione a função próxima ao bloco examinado. Preserve os decorators e a permissão indicados no roteiro.</p><div class="fileline">edu/views.py · próximo à view relatorio_horario</div><pre class="codebox" style="padding:18px"><code>${escape(newScreenView)}</code></pre><ul><li><code>@rtr('treinamento_fluxo_web.html')</code> informa explicitamente qual template será renderizado.</li><li><code>@permission_required('edu.view_horarioauladiario')</code> restringe a execução da view a usuários autorizados.</li><li><code>title</code> e <code>links</code> são variáveis que o template poderá utilizar.</li><li><code>return locals()</code> reúne as variáveis locais no dicionário de contexto processado por <code>@rtr</code>.</li></ul><div class="tip"><strong>Segurança:</strong> a autorização está na view. Ocultar um link ou botão no template não substitui a verificação feita no servidor.</div><h3>Passo 4 · Crie o template</h3><p>Crie o arquivo <code>edu/templates/treinamento_fluxo_web.html</code> com o conteúdo abaixo.</p><div class="fileline">edu/templates/treinamento_fluxo_web.html · arquivo novo</div><pre class="codebox" style="padding:18px"><code>${escape(newScreenTemplate)}</code></pre><ul><li><code>{% extends super_template %}</code> reutiliza o layout padrão do SUAP.</li><li><code>{% box %}</code> organiza o conteúdo em blocos visuais do sistema.</li><li><code>{% for label, url in links %}</code> percorre a lista preparada pela view.</li><li><code>{{ links|length }}</code> aplica o filtro <code>length</code> para apresentar a quantidade de links.</li></ul><h3>Passo 5 · Verifique o fluxo completo</h3><ol><li>Acesse <code>/edu/treinamento_fluxo_web/</code> com um usuário autorizado no ambiente de desenvolvimento.</li><li>Confirme que a rota chama a nova view e que a página usa o layout do SUAP.</li><li>Verifique se o título, os três links e o total de links aparecem no template.</li><li>Teste com um usuário sem a permissão indicada e confirme que a proteção ocorre no servidor.</li><li>Se algo falhar, percorra novamente a sequência: URL → view → decorators → contexto → template.</li></ol><p class="small muted">Fonte: <code>fontes/fluxo_01.md</code>, seção III — Criar uma Tela Nova. Referências baseadas no checkout do commit 936e818c17; as linhas podem mudar em outras versões.</p></section>`}
function challengeArea(moduleId){const items=moduleChallenges[moduleId]||[];if(!items.length)return '';const done=items.filter(c=>state['ticket:'+moduleId+':'+c.id]).length;return `<section class="lesson challenge-area" id="chamados"><span class="tag">LABORATÓRIO DE CHAMADOS</span><h2>Chamados simulados</h2><p>Assuma o atendimento dos pedidos abaixo. Para cada chamado, localize o fluxo responsável pela tela, identifique o arquivo correto, implemente a menor alteração necessária e valide o critério de aceite.</p><div class="warn"><strong>Ambiente de treinamento:</strong> não altere o SUAP de produção nem utilize dados pessoais reais. As URLs indicam a tela de referência; execute e teste as mudanças em seu ambiente de desenvolvimento.</div><div class="ticket-grid">${items.map((c,i)=>`<article class="ticket-card ${c.duplicate?'ticket-duplicate':''}"><div class="ticket-heading"><span class="ticket-number">CHAMADO ${String(i+1).padStart(2,'0')}</span>${c.duplicate?'<span class="ticket-status">VERIFICAR DUPLICIDADE</span>':''}</div><h3>${escape(c.title)}</h3><p class="ticket-area">${escape(c.area)}</p><div class="ticket-block"><strong>Solicitação</strong><p>${escape(c.request)}</p></div><div class="ticket-block"><strong>Tela de referência</strong><code>${escape(c.url)}</code></div><div class="ticket-block"><strong>Critério de aceite</strong><p>${escape(c.acceptance)}</p></div><label class="ticket-check"><input type="checkbox" data-ticket="${moduleId}:${escape(c.id)}" ${state['ticket:'+moduleId+':'+c.id]?'checked':''}><span>Atendimento concluído e validado</span></label></article>`).join('')}</div><div class="bar"><div style="width:${Math.round(done/items.length*100)}%"></div></div><p class="muted small">${done} de ${items.length} chamados concluídos · Progresso salvo neste navegador</p></section>`}
function tasks(m){return `<section class="lesson" id="atividades"><span class="tag">AGORA É SUA VEZ</span><h2>Atividade prática orientada</h2><p>Realize as etapas no repositório de desenvolvimento. Marque cada uma quando conseguir explicar o resultado.</p>${m.tasks.map((t,i)=>`<label class="task"><input type="checkbox" data-task="${m.id}:${i}" ${state['task:'+m.id+':'+i]?'checked':''}><span>${t}</span></label>`).join('')}<div class="bar"><div style="width:${Math.round(taskDone(m)/m.tasks.length*100)}%"></div></div><p class="muted small">${taskDone(m)} de ${m.tasks.length} concluídas · Salvo neste navegador</p></section>`}
function quiz(m){return `<section class="lesson"><span class="tag">VERIFIQUE SUA COMPREENSÃO</span><h2>Questões de revisão</h2><p>Escolha uma alternativa para receber uma explicação imediata.</p>${m.quiz.map((q,i)=>`<div class="question"><h3>${i+1}. ${q[0]}</h3>${q[1].map((opt,j)=>`<label><input type="radio" name="q-${m.id}-${i}" data-quiz="${m.id}:${i}:${j}" ${state['quiz:'+m.id+':'+i]===j?'checked':''}> ${escape(opt)}</label>`).join('')}<div id="feedback-${m.id}-${i}">${state['quiz:'+m.id+':'+i]===undefined?'':feedback(m,i)}</div></div>`).join('')}</section>`}
function feedback(m,i){let q=m.quiz[i],ok=state['quiz:'+m.id+':'+i]===q[2];return `<div class="feedback ${ok?'correct':''}">${ok?'✓ Correto.':'Reveja este conceito.'} ${escape(q[3])}</div>`}
function notesBlock(id){return `<section class="lesson"><span class="tag">REGISTRO DE APRENDIZAGEM</span><h2>Minhas descobertas</h2><p class="muted">Anote dúvidas, arquivos encontrados e conclusões. O texto fica salvo apenas neste navegador.</p><textarea data-note="${id}" placeholder="Ex.: Encontrei a função em edu/views.py e percebi que...">${escape(state['note:'+id]||'')}</textarea><div class="codebar"><span class="muted small">Salvamento automático local</span><button class="btn secondary" data-export="${id}">Exportar anotações (.md) ↓</button></div></section>`}
function module1(){return `<div class="lesson"><h2>1. Entenda o caminho de uma requisição</h2><p>Ao acessar uma turma, o Django identifica a rota em <code>urls.py</code> e encaminha a requisição para uma view. A view recupera dados dos models, aplica as regras necessárias e prepara o contexto para o template.</p><img class="diagram" src="fluxo_django_mtv.png" alt="Fluxo de requisição Django"><div class="tip"><strong>Conexão com o EDU:</strong> a função <code>turma(request, pk)</code> consulta o model <code>Turma</code>, recupera matrículas e horários e prepara variáveis para a página.</div><h3>Arquivos para reconhecer</h3><p>Uma tela no SUAP normalmente combina rota, lógica da aplicação, consultas ao banco e apresentação. Reconheça a responsabilidade de cada arquivo para saber onde começar uma investigação.</p><div class="tablewrap"><table><thead><tr><th scope="col">Arquivo ou diretório</th><th scope="col">Responsabilidade no fluxo web</th></tr></thead><tbody>${row('<code>edu/urls.py</code>','Define as rotas do módulo e determina qual view será executada quando você acessar uma URL. Existe também um <code>urls.py</code> geral da aplicação; cada módulo pode ter seu próprio arquivo de rotas. Pense na URL como o endereço de um guichê: ela encaminha a requisição para o atendimento correto.') }${row('<code>edu/views.py</code>','Processa a requisição, executa a lógica da aplicação, busca dados e retorna uma resposta. Na prática, a view costuma verificar permissões, buscar objetos no banco e preparar variáveis para o template. A resposta pode ser HTML, PDF, XLS, JSON ou um redirecionamento.') }${row('<code>edu/templates/</code>','Contém os templates que definem como o conteúdo será apresentado. Eles recebem variáveis preparadas pela view, como <code>obj</code>, <code>title</code>, <code>form</code>, <code>alunos</code>, <code>turnos</code> e <code>diarios_por_sigla</code>, e organizam esses dados em HTML.') }${row('<code>edu/admin.py</code>','Configura a interface administrativa do Django/SUAP para visualizar, cadastrar, editar e excluir registros, sem criar uma tela administrativa do zero. Observe as configurações de colunas da listagem, filtros, campos de busca, exportação e permissões de exibição.') }${row('<code>edu/forms.py</code>','Define os formulários usados para entrada de dados. Pode estabelecer campos visíveis, validações, filtros de queryset, organização visual dos campos e processamento dos dados enviados pelo usuário.') }${row('<code>edu/models/</code><br>Exemplo: <code>edu/models/turmas.py</code>','Define os modelos de dados: entidades gravadas e manipuladas no banco, como <code>Aluno</code>, <code>Turma</code>, <code>Diario</code>, <code>CursoCampus</code> e <code>MatriculaPeriodo</code>. O roteiro apresenta essa responsabilidade como <code>models.py</code>; no EDU, os models estão distribuídos em <code>edu/models/*.py</code>. O arquivo <code>turmas.py</code> contém o model <code>Turma</code> e suas regras.') }</tbody></table></div><div class="tip"><strong>Ao investigar uma manutenção:</strong> siga a rota até a view, identifique os dados e as regras envolvidos e localize o template responsável pela apresentação. Conforme a demanda, consulte também forms, models e admin; raramente um único arquivo explica toda a tela.</div><p class="small muted">Descrições adaptadas da introdução de <code>fontes/fluxo_01.md</code>, com a organização dos models do EDU indicada no plano de curso.</p></div>${code('model','2. Conheça o model Turma','Observe a declaração dos managers, os campos acadêmicos e os relacionamentos com CursoCampus, Matriz, Turno e CalendarioAcademico.')}${code('matriculados','3. De onde vêm os alunos?','Compare os métodos de matrículas diretas e de matrículas relacionadas a diários. Observe filter(), exclude(), select_related() e distinct().')}${code('horarios','4. Como a turma organiza os horários?','O método get_horarios() consulta turnos e horários, organiza os dias da semana e considera o semestre informado.')}${code('view','5. Leia a view turma() comentada','Use o botão para ocultar comentários e tentar explicar o código com suas próprias palavras. O trecho é uma versão didática comentada da view fornecida.')}${newScreenLesson()}`}
function snippet(source){return `<pre class="codebox" style="padding:18px"><code>${escape(source)}</code></pre>`}
function module2(){return `<section class="lesson"><span class="tag">LEITURA DE VIEWS</span><h2>1. Como os decorators participam da execução</h2><p>Em <code>edu/views.py</code>, decorators são funções que envolvem uma view para acrescentar comportamento antes ou depois de sua execução. Leia sempre os decorators antes do corpo da função: eles revelam exigências de acesso, renderização, transação e tipo de resposta.</p>${snippet(decoratorOrderExample)}<ol><li>A permissão é verificada.</li><li>A view é executada.</li><li>O retorno da view é renderizado.</li></ol><div class="tip"><strong>Ordem:</strong> o decorator mais próximo da função é aplicado primeiro. Durante a requisição, porém, o decorator escrito acima costuma interceptar a chamada antes dos demais.</div></section><section class="lesson"><h2>2. <code>@rtr()</code>: dados transformados em tela</h2><p><code>@rtr()</code> é um dos decorators mais importantes do SUAP. Ele renderiza o retorno da view em um template.</p><div class="fileline">Importado em edu/views.py · implementação indicada no roteiro: djtools/utils/response.py:148</div><ul><li>Sem um template informado, tenta descobri-lo pelo nome da view.</li><li>Com um template informado, renderiza o arquivo específico.</li><li>Se a view já retornar <code>HttpResponse</code>, <code>HttpResponseRedirect</code>, PDF, XLS ou outra resposta pronta, devolve essa resposta sem tentar renderizar outro template.</li></ul><h3>Template descoberto pela convenção</h3>${snippet(rtrImplicitExample)}<h3>Template informado explicitamente</h3>${snippet(rtrExplicitExample)}<div class="tip"><strong>Uma forma de memorizar:</strong> <code>@rtr()</code> pega o envelope de dados retornado pela view e o transforma em tela.</div></section>${code('gettemplate','Como o SUAP escolhe o template','Quando @rtr() não recebe um nome, get_template_path() deriva o caminho a partir do módulo e do nome da função.')}${code('rtr','A implementação real de @rtr()','Observe a chamada à função decorada, o teste de HttpResponse e a renderização do dicionário retornado.') }<section class="lesson"><h2>3. <code>@permission_required(...)</code>: acesso por permissão</h2><p>Esse decorator verifica se o usuário possui a permissão informada. Caso não possua, levanta <code>PermissionDenied</code>.</p><div class="fileline">Exemplo: edu/views.py:1684 · implementação: djtools/utils/__init__.py:1783</div>${snippet(permissionExamples)}<ul><li>Uma string exige aquela permissão específica.</li><li>Uma lista usa lógica <code>or</code> por padrão: basta possuir uma das permissões.</li><li>Com <code>logic_operator='and'</code>, todas as permissões da lista se tornam obrigatórias.</li></ul><p>Utilize esse decorator quando a regra vier de permissões Django ou das permissões declaradas em <code>permissions.yaml</code>.</p></section><section class="lesson"><h2>4. <code>@group_required(...)</code>: acesso por grupo</h2><p><code>@group_required</code> é semelhante ao decorator de permissão, mas verifica diretamente os grupos do usuário.</p><div class="fileline">Exemplo: edu/views.py:4559 · implementação: djtools/utils/__init__.py:1753</div>${snippet(groupRequiredExample)}<ul><li>Use <code>@group_required</code> quando a regra disser diretamente que determinados perfis ou grupos podem acessar.</li><li>Use <code>@permission_required</code> quando o acesso depender de permissões como <code>edu.view_aluno</code>, <code>edu.change_diario</code> ou <code>edu.gerar_relatorio</code>.</li></ul></section><section class="lesson"><h2>5. <code>@login_required</code>: usuário autenticado</h2><p>Este é o decorator padrão do Django para exigir que o usuário esteja autenticado. As formas com e sem parênteses aparecem no código.</p><div class="fileline">Exemplo indicado no roteiro: edu/views.py:6204</div>${snippet(loginRequiredExample)}<div class="tablewrap"><table><thead><tr><th>Decorator</th><th>O que exige</th></tr></thead><tbody><tr><td><code>@login_required</code></td><td>Usuário autenticado.</td></tr><tr><td><code>@permission_required</code></td><td>Permissão específica.</td></tr><tr><td><code>@group_required</code></td><td>Pertencimento a grupo específico.</td></tr></tbody></table></div></section><section class="lesson"><h2>6. <code>@documento(...)</code>: HTML transformado em PDF</h2><p><code>@documento</code> transforma o HTML produzido pela view em PDF ou documento.</p><div class="fileline">Exemplo: edu/views.py:1684 · implementação: djtools/utils/__init__.py:1360</div>${snippet(documentoPatternExample)}<ol><li><code>@rtr</code> renderiza o HTML.</li><li><code>@documento</code> transforma o HTML em PDF.</li></ol><h3>Parâmetros importantes</h3><div class="tablewrap"><table><thead><tr><th>Parâmetro</th><th>Efeito</th><th>Referência</th></tr></thead><tbody><tr><td><code>landscape=True</code></td><td>Gera o PDF em modo paisagem.</td><td><code>edu/views.py:6245</code></td></tr><tr><td><code>enumerar_paginas=False</code></td><td>Remove a numeração das páginas.</td><td>Roteiro fluxo 02</td></tr><tr><td><code>validade=30</code></td><td>Adiciona uma mensagem de validade do documento.</td><td>Roteiro fluxo 02</td></tr><tr><td><code>modelo='edu.aluno'</code></td><td>Associa o documento ao model indicado.</td><td>Roteiro fluxo 02</td></tr></tbody></table></div>${snippet(documentoParametersExample)}<h3>Primeiro parâmetro e autenticação</h3><p>Quando o primeiro parâmetro é informado, como em <code>@documento('Qualquer Coisa')</code>, ele se torna o <code>tipo_para_verificacao</code>. O SUAP passa a:</p><ul><li>gerar <code>codigo_verificador</code>;</li><li>inserir o Código de Autenticação no PDF;</li><li>registrar o documento em <code>RegistroEmissaoDocumento</code>;</li><li>permitir a validação em <code>/comum/autenticar_documento/</code>.</li></ul><div class="fileline">Geração do código: djtools/utils/__init__.py:1423 · rodapé: linhas 1500–1508 · registro: linhas 1557–1595</div><p>Para um PDF simples, sem autenticador, utilize <code>@documento()</code> sem o primeiro parâmetro textual.</p></section><section class="lesson"><h2>7. <code>@transaction.atomic</code>: consistência das gravações</h2><p>Esse decorator do Django executa as operações de banco da view dentro de uma transação. Se ocorrer um erro, o banco pode realizar rollback.</p><div class="fileline">Referências: edu/views.py:3568 e edu/views.py:3596</div><div class="tip"><strong>Uma forma de memorizar:</strong> ou salva tudo, ou não salva nada. Utilize em ações que gravam dados e precisam manter consistência.</div></section><section class="lesson"><h2>8. <code>@csrf_exempt</code>: exceção à proteção CSRF</h2><p><code>@csrf_exempt</code> remove a exigência do token CSRF para aquela view.</p><div class="fileline">Referência: edu/views.py:4274</div><div class="warn"><strong>Atenção:</strong> CSRF protege requisições POST contra envios maliciosos originados em outros sites. Use essa exceção somente quando houver uma justificativa clara e após avaliar o risco.</div></section><section class="lesson"><h2>9. <code>@documentos.emissao_documentos()</code>: participação em um sinal</h2><p>Este decorator é diferente dos anteriores: não corresponde a uma view comum atendida por uma URL. Ele conecta uma função ao sinal de emissão de documentos. Quando o mecanismo dispara esse sinal, a função decorada participa preenchendo dados ou tratando a emissão.</p><div class="fileline">Exemplo: edu/views.py:481 · implementação: djtools/documentos.py:6</div></section><section class="lesson"><span class="tag">RECURSOS RELACIONADOS</span><h2>Respostas e redirecionamentos</h2><p>Os elementos abaixo não são decorators, mas ajudam a compreender os retornos que <code>@rtr()</code> pode receber e devolver diretamente.</p></section>${code('httprr','Redirecionamentos com httprr()','O helper registra mensagens de sucesso ou erro e devolve HttpResponseRedirect; também trata cenários de popup.')}${code('pdfresponse','Resposta pronta com PDFResponse','PDFResponse usa o content type application/pdf e permite indicar exibição inline ou download por anexo.') }<section class="lesson"><span class="tag">EXEMPLO PRÁTICO</span><h2>Exemplo Prático: Criar PDF com Dados Gerais do Aluno</h2><p>O objetivo é acrescentar à tela do aluno um botão que gere um PDF com seus dados gerais.</p><ol><li>Criar a URL.</li><li>Adicionar o botão à tela do aluno.</li><li>Criar a view PDF.</li><li>Criar o template PDF.</li><li>Testar o resultado.</li></ol><h3>1. Crie a URL</h3><p>Em <code>edu/urls.py</code>, adicione a rota perto das rotas de documentos do aluno.</p>${snippet(studentPdfRoute)}<ul><li><code>pk</code> é o identificador interno do aluno.</li><li>A URL chama a view <code>dados_gerais_aluno_pdf</code>.</li></ul><h3>2. Adicione o botão à tela do aluno</h3><p>Em <code>edu/templates/aluno.html</code>, adicione o item dentro do bloco <code>action-bar</code>.</p>${snippet(studentPdfButton)}<ul><li><code>obj.pk</code> vem da view <code>aluno</code>.</li><li>O botão aponta para a nova URL.</li><li>Neste exercício, o botão permanece simples para facilitar a compreensão do fluxo.</li><li>Em uma demanda real, avalie quais perfis podem visualizar a ação.</li></ul><h3>3. Crie a view PDF</h3><p>Adicione a função em <code>edu/views.py</code>, próxima de <code>atestadofrequencia_pdf</code>, indicada no roteiro nas linhas 6944–6976.</p>${snippet(studentPdfView)}<ul><li><code>@login_required</code> exige usuário autenticado.</li><li><code>@documento(...)</code> gera o PDF.</li><li>O texto <code>Dados Gerais do Aluno</code> faz o documento receber código de autenticação.</li><li><code>@rtr('dados_gerais_aluno_pdf.html')</code> renderiza o template antes da conversão.</li><li>As variáveis de permissão foram simplificadas exclusivamente para o treinamento.</li></ul><div class="warn"><strong>Não leve as permissões fixas para uma demanda real.</strong> Não mantenha <code>is_admin = True</code>, <code>pode_ver_cpf = True</code> ou equivalentes em produção. Reaproveite as regras contextuais da view <code>aluno</code> e trabalhe apenas com dados fictícios no treinamento.</div><h3>4. Crie o template PDF</h3><p>Crie o arquivo <code>edu/templates/dados_gerais_aluno_pdf.html</code>. O template completo do roteiro está reproduzido abaixo.</p>${snippet(studentPdfTemplate)}<h3>5. Teste o resultado</h3><ol><li>Abra a tela de um aluno fictício no ambiente de desenvolvimento.</li><li>Verifique se o botão <code>Gerar PDF - Dados Gerais</code> aparece.</li><li>Acione o botão e confirme que o PDF abre.</li><li>Confira se o código de autenticação foi incluído.</li><li>Acrescente <code>?html=1</code> à URL para depurar o HTML antes da conversão em PDF.</li><li>Valide novamente as regras de acesso com perfis permitidos e não permitidos.</li></ol></section><section class="lesson"><span class="tag">FECHAMENTO</span><h2>Leia primeiro os decorators</h2><ul><li>Decorators controlam o comportamento da view.</li><li><code>@rtr</code> transforma dados em HTML.</li><li><code>@documento</code> transforma HTML em PDF.</li><li><code>@documento('Tipo')</code> cria um documento autenticável.</li><li>O template PDF deve ser mais simples que a tela normal.</li><li>Uma simplificação de treinamento nunca substitui as regras cuidadosas exigidas em produção.</li></ul><p><strong>Ao investigar uma view no SUAP, comece pelos decorators:</strong> eles revelam permissões, renderização, transações e o tipo de resposta.</p><p class="small muted">Fonte: <code>fontes/fluxo_02.md</code>. As linhas pertencem ao checkout de referência e devem ser conferidas após mudanças no repositório.</p></section>`}
const module3LessonHtml="<section class=\"panel\"><span class=\"tag\">ENCONTRO 3 · EXPLORAÇÃO E DIAGNÓSTICO</span><h2>Da declaração à autorização</h2><p>Compreenda os grupos, siga a sincronização, localize as cinco camadas de checagem e pratique o diagnóstico. Depois, compare os chamados 1144, 1168 e 1157.</p><p>Fonte: <code>fontes/fluxo_03.md</code>. Caminhos, linhas e merges foram informados pelo roteiro e precisam ser conferidos no checkout SUAP. O plano registra o commit de referência <code>936e818c17</code>; os diffs não estão anexados.</p><div class=\"warn\">As práticas exigem acesso ao repositório SUAP e a um ambiente isolado com dados fictícios. Sem esse acesso, analise os trechos e registre hipóteses e verificações necessárias. Não execute sincronização nem altere permissões em produção. Substitua o marcador de matrícula pela matrícula fictícia do ambiente.</div></section><p>Objetivo: explicar como o SUAP organiza grupos e permissões, como o <code>permissions.yaml</code> alimenta essas permissões e onde elas são verificadas nas telas, menus, views, templates e managers.</p><section class=\"lesson\"><h2>I. Conceito de Grupos no SUAP</h2><p>Compreenda que grupo e uma forma de atribuir um conjunto de permissões a vários usuários.</p><p>Uma forma de compreender: em vez de dar permissão usuário por usuário, o SUAP coloca o usuário em um grupo; o grupo carrega as permissões.</p><h3>1. Observe na tela</h3><p>Na interface administrativa, observe um usuário e seus grupos.</p><p>Observe estas relações:</p><ul><li>Um usuário pode pertencer a vários grupos.</li><li>Um grupo pode ter várias permissões.</li><li>A permissão efetiva do usuário e a soma das permissões dos grupos dele, mais permissões diretas, se existirem.</li></ul><p>Exemplo de grupos no contexto EDU:</p><ul><li><code>Administrador Acadêmico</code>;</li><li><code>Secretário Acadêmico</code>;</li><li><code>Coordenador de Curso</code>;</li><li><code>Organizador de Minicurso</code>;</li><li><code>Diretor Acadêmico</code>.</li></ul><h3>2. Observe no <code>permissions.yaml</code></h3><p>Arquivo: <code>edu/permissions.yaml</code>.</p><p>Observe: o arquivo declara quais permissões cada grupo deve receber.</p><p>Exemplo em <code>edu/permissions.yaml:46-52</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>Administrador Acadêmico:\n  edu:\n    aluno:\n    - view_aluno\n    - view_dados_academicos\n    - view_dados_pessoais</code></pre><p>Leitura:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>Grupo: Administrador Acadêmico\nApp: edu\nModelo: aluno\nPermissao: view_aluno\nPermissao completa: edu.view_aluno</code></pre><p>Ponto importante: o YAML declara permissões para grupos, mas ele não e consultado diretamente por cada tela em tempo real.</p><h3>3. Compreender grupos e permissões</h3><p>Analise a diferenca:</p><ul><li>Grupo: conjunto de usuários com um papel comum.</li><li>Permissão: capacidade de realizar ou visualizar algo no sistema.</li><li>Codename: nome técnico da permissão, como <code>view_aluno</code>.</li><li>Permissão completa: <code>app.codename</code>, como <code>edu.view_aluno</code>.</li></ul><p>Exemplo:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>request.user.has_perm(&#39;edu.view_aluno&#39;)</code></pre><p>Essa linha pergunta: o usuário logado possui a permissão <code>view_aluno</code> do app <code>edu</code>?</p><h3>4. Compreender o <code>edu/perms.py</code></h3><p>Arquivo: <code>edu/perms.py</code>.</p><p>Observe: <code>permissions.yaml</code> diz quais permissões o grupo possui. Ja o <code>perms.py</code> concentra regras contextuais.</p><p>Exemplo: não basta perguntar &quot;tem permissão?&quot;. As vezes a pergunta real e:</p><ul><li>pode atuar neste curso?</li><li>e do mesmo campus?</li><li>e coordenador deste curso?</li><li>pode mexer em ENADE deste aluno?</li><li>e o próprio aluno?</li></ul><p>Exemplo em <code>edu/perms.py:92-106</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>def pode_realizar_procedimentos_enade(user, curso_campus):\n    ...</code></pre><p>Essa função decide se o usuário pode realizar procedimentos ENADE naquele curso especifico.</p><p>Uma forma de compreender: o <code>permissions.yaml</code> entrega o crachá; o <code>perms.py</code> decide se aquele crachá vale naquele contexto.</p></section><section class=\"lesson\"><h2>II. Como o <code>permissions.yaml</code> Vira Permissão no Banco</h2><h3>1. Comando <code>sync_permissions</code></h3><p>Depois que o <code>sync_permissions</code> roda, os grupos recebem as permissões declaradas no YAML.</p><p>Referencia:</p><ul><li>O comando procura arquivos <code>permissions.yaml</code> em <code>djtools/management/commands/sync_permissions.py:137</code>.</li></ul><p>Trecho importante:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>permissionFileName = f&#39;{app}/permissions.yaml&#39;</code></pre><h3>2. Função <code>sync_groups_and_permissions</code></h3><p>Implementacao: <code>djtools/utils/__init__.py:1650</code>.</p><p>Essa função:</p><ul><li>cria ou obtem o grupo;</li><li>localiza as permissões Django;</li><li>associa as permissões ao grupo.</li></ul><p>Trecho conceitual:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>group, created = Group.objects.get_or_create(name=group_name)\ngroup.permissions.add(perm)</code></pre><h3>3. Fluxo completo</h3><p>Analise o fluxo nesta ordem:</p><ol><li>Você declara a permissão no <code>permissions.yaml</code>.</li><li>O comando <code>sync_permissions</code> lê esse arquivo.</li><li>O SUAP cria/atualiza grupos e associa permissões Django.</li><li>Quando o usuário acessa uma tela, o sistema checa <code>user.has_perm(...)</code>, decorators, templates, menus ou managers.</li><li>Se o usuário pertence a um grupo que recebeu aquela permissão, a checagem passa.</li></ol><p>Resumo: o YAML alimenta o banco. A tela consulta as permissões já sincronizadas no banco.</p></section><section class=\"lesson\"><h2>III. Como as Telas Checam Permissões</h2><h3>1. Na view com <code>has_perm</code></h3><p>Exemplo em <code>edu/views.py:11270-11275</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>if (\n    not request.user.has_perm(&#39;edu.efetuar_matricula&#39;)\n    and not request.user.has_perm(&#39;edu.gerar_relatorio&#39;)\n    and not request.user.has_perm(&#39;edu.view_aluno&#39;)\n):\n    return httprr(&#39;/&#39;, &#39;Você não tem permissão para acessar essa página&#39;, &#39;error&#39;)</code></pre><p>Explicação:</p><ul><li>A view verifica permissões diretamente.</li><li>Se o usuário não tiver nenhuma das permissões aceitas, ele e bloqueado.</li></ul><p>Outro exemplo importante: tela do aluno em <code>edu/views.py:4703</code>.</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>request.user.has_perm(&#39;edu.view_aluno&#39;)</code></pre><h3>2. No template com <code>perms.edu.view_aluno</code></h3><p>Exemplo em <code>edu/templates/relatorio.html:159-161</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>{% if perms.edu.view_aluno %}\n    &lt;a target=&quot;_blank&quot; href=&quot;{{ aluno.get_absolute_url }}&quot;&gt;{{ aluno.matricula }}&lt;/a&gt;\n{% else %}\n    {{ aluno.matricula }}\n{% endif %}</code></pre><p>Explicação:</p><ul><li>Se o usuário tem permissão, o template mostra um link.</li><li>Se não tem, mostra apenas a matrícula.</li><li>Isso controla apresentacao, não substitui a validacao na view de destino.</li></ul><h3>3. No menu</h3><p>Arquivo: <code>edu/menu.yaml:8-11</code>.</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>Ensino::Alunos e Professores::Alunos:\n  permissions_required:\n  - edu.view_aluno\n  url: /admin/edu/aluno/correntes</code></pre><p>Explicação:</p><ul><li>A permissão controla se o item de menu aparece.</li><li>Se o usuário não tem <code>edu.view_aluno</code>, o menu não deve ser exibido.</li><li>Mas esconder menu não bloqueia URL direta; a view/admin também precisa validar.</li></ul><h3>4. Em decorators</h3><p>Exemplo em <code>edu/views.py:11837-11839</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>@rtr()\n@permission_required(&#39;edu.view_convocacaoenade&#39;)\ndef convocados_enade(request, pk, curso_campus_pk):</code></pre><p>Explicação:</p><ul><li>O decorator verifica a permissão antes de executar a view.</li><li>Se o usuário não possuir a permissão, a view não roda.</li></ul><h3>5. Em managers/querysets</h3><p>Exemplo em <code>edu/managers.py:671-681</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>if user.groups.filter(permissions__codename=&#39;view_aluno&#39;).count() == 1:\n    ...\n    return qs.filter(polo__id__in=ids)</code></pre><p>Explicação:</p><ul><li>A permissão também pode influenciar o conjunto de objetos visiveis.</li><li>Aqui, a regra afeta quais alunos aparecem para determinado perfil.</li></ul></section><section class=\"lesson\"><h2>IV. Como Analisar Demandas de Permissão</h2><p>Use este checklist:</p><ol><li>A permissão existe no <code>permissions.yaml</code>?</li><li>O grupo correto recebeu essa permissão?</li><li>O <code>sync_permissions</code> foi executado?</li><li>A view, template, menu ou manager realmente consulta essa permissão?</li><li>Existe regra contextual adicional em <code>views.py</code>, <code>perms.py</code> ou managers?</li><li>A mudanca envolve dados pessoais ou acadêmicos sensiveis?</li><li>Esconder botão e suficiente ou a URL também precisa ser bloqueada?</li></ol><p>Uma forma de compreender: permissão no SUAP raramente está em um unico lugar; ela pode estar declarada no YAML, aplicada pelo sync, checada na view, filtrada no manager e exibida no template.</p></section><section class=\"lesson\"><h2>V. Exemplos Praticos</h2><h3>1. Remover acesso aos detalhes da tela do aluno</h3><p>Tela de exemplo:</p><ul><li><code>http://localhost:8000/edu/aluno/&lt;matricula_ficticia&gt;/</code></li></ul><p>Perfil sugerido:</p><ul><li><code>Secretário Acadêmico</code>.</li></ul><p>Roteiro:</p><ol><li>Observe o usuário com permissão.</li><li>Abrir a tela do aluno e confirmar que o acesso funciona.</li><li>Localizar o grupo no <code>edu/permissions.yaml</code>.</li><li>Remover temporariamente a permissão relacionada, por exemplo <code>view_aluno</code>.</li><li>Rodar <code>sync_permissions</code>.</li><li>Testar novamente com o mesmo usuário.</li><li>Compreender se o bloqueio veio da view, do menu, do manager ou de outra regra.</li></ol><p>Ponto de cuidado: remover <code>view_aluno</code> pode afetar várias telas, links e consultas, não apenas a tela de detalhe.</p><h3>2. Remover botão <code>Adicionar Aluno</code> do admin de aluno</h3><p>Tela:</p><ul><li><code>http://localhost:8000/admin/edu/aluno/</code></li></ul><p>Perfil sugerido:</p><ul><li><code>Secretário Acadêmico</code>.</li></ul><p>Roteiro:</p><ol><li>Observe o usuário com permissão.</li><li>Abrir o admin de aluno e observar o botão <code>Adicionar Aluno</code>.</li><li>Identificar qual permissão controla adição de aluno, normalmente <code>edu.add_aluno</code>.</li><li>Remover temporariamente essa permissão do grupo no <code>permissions.yaml</code>.</li><li>Rodar <code>sync_permissions</code>.</li><li>Testar novamente.</li><li>Compreender que o admin do Django usa permissões <code>add</code>, <code>change</code>, <code>delete</code> e <code>view</code> para controlar botões e ações.</li></ol><p>Ponto de cuidado: remover <code>add_aluno</code> não deve ser tratado como mudanca visual; e uma alteração de permissão real no admin.</p></section><section class=\"lesson\"><h2>VI. Chamados Atendidos</h2><h3>1. Issue 1144: permissões para <code>Organizador de Minicurso</code></h3><p>Contexto: o grupo <code>Organizador de Minicurso</code> precisava visualizar dados de aluno.</p><p>Localize e análise o diff do merge no repositório SUAP:</p><ul><li><code>400d69076d</code></li></ul><p>Arquivo:</p><ul><li><code>edu/permissions.yaml:2101-2107</code></li></ul><p>Estado atual:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>Organizador de Minicurso:\n  description: Usuários deste grupo gerenciam os minicursos.\n  edu:\n    aluno:\n    - view_aluno\n    - view_dados_academicos\n    - view_dados_pessoais</code></pre><p>Compreender:</p><ul><li><code>edu.view_aluno</code>: permite passar por verificacoes gerais de visualizacao de aluno.</li><li><code>edu.view_dados_academicos</code>: participa da regra <code>pode_ver_dados_academicos</code> em <code>edu/views.py:4666-4672</code>.</li><li><code>edu.view_dados_pessoais</code>: aparece em condições de template, por exemplo <code>edu/templates/aluno.html:402-407</code>.</li></ul><p>Observe a condição no template:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>{% if perms.edu.view_dados_pessoais or is_proprio_aluno %}</code></pre><p>Cuidado: conceder acesso a dados pessoais e acadêmicos amplia acesso a informações sensiveis. A análise deve registrar grupo, motivo, telas afetadas e escopo.</p><h3>2. Issue 1168: <code>Secretário Acadêmico</code> na aba ENADE</h3><p>Contexto: a demanda não foi resolvida apenas no <code>permissions.yaml</code>; ela alterou uma regra contextual em <code>edu/perms.py</code>.</p><p>Localize e análise o diff do merge no repositório SUAP:</p><ul><li><code>051aed03cd</code></li></ul><p>Arquivo:</p><ul><li><code>edu/perms.py:92-106</code></li></ul><p>Ponto central:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>autorizado = UsuarioGrupo.objects.filter(\n    user=user,\n    group__name__in=[\n        &#39;Administrador Acadêmico&#39;,\n        &#39;Diretor de Avaliação e Regulação do Ensino&#39;,\n        &#39;Operador ENADE&#39;,\n        &#39;Secretário Acadêmico&#39;,\n    ],\n).exists()</code></pre><p>Na tela do aluno, examine <code>edu/views.py:5099-5101</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>pode_realizar_procedimentos_enade = perms.pode_realizar_procedimentos_enade(request.user, obj.curso_campus) and not obj.is_concluido()</code></pre><p>No template da aba ENADE, examine <code>edu/templates/tabs/aluno_convocacoes_enade.html:17-18</code>:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>{% if pode_realizar_procedimentos_enade or is_coordenador %}\n    &lt;th class=&quot;no-print&quot;&gt;Opções&lt;/th&gt;\n{% endif %}</code></pre><p>Explicação:</p><ul><li><code>permissions.yaml</code> diz quais permissões o grupo tem.</li><li><code>pode_realizar_procedimentos_enade</code> decide se o usuário pode realizar procedimentos ENADE naquele curso.</li><li>O template decide se mostra opções de acao.</li></ul><h3>3. Issue 1157: remover opção <code>Documentos</code> para alunos especiais</h3><p>Contexto: a issue removeu o botão/menu <code>Documentos</code> para alunos especiais.</p><p>Localize e análise o diff do merge no repositório SUAP:</p><ul><li><code>6fae1e80a6</code></li></ul><p>Arquivo:</p><ul><li><code>edu/templates/aluno.html:188-195</code></li></ul><p>Condicao atual:</p><div class=\"fileline\">Trecho reproduzido do roteiro · reticências indicam conteúdo omitido</div><pre class=\"codebox\" style=\"padding:18px\"><code>{% if not obj.aluno_especial %}\n    &lt;a class=&quot;btn default&quot; href=&quot;#&quot;&gt;Documentos&lt;/a&gt;\n{% endif %}</code></pre><p>Explicação:</p><ul><li>Este caso tem relação com permissão porque muda a experiencia de acesso conforme perfil/situação do aluno.</li><li>Mas isso e apenas controle visual.</li><li>Os links internos continuam no bloco abaixo, em <code>urls_documentos</code>.</li><li>Se a regra precisa impedir acesso direto ao documento, deve existir validacao na view do documento, não apenas no template.</li></ul></section><section class=\"lesson\"><h2>VII. Fechamento</h2><p>Revise as responsabilidades:</p><ul><li><code>permissions.yaml</code> declara permissões dos grupos.</li><li><code>sync_permissions</code> grava essas permissões no banco.</li><li><code>has_perm</code>, decorators, templates, menus e managers consultam essas permissões.</li><li><code>perms.py</code> trata regras contextuais.</li><li>Template pode esconder um botão, mas não deve ser a unica proteção.</li></ul><p>Ao investigar um chamado: para resolver chamado de permissão com seguranca, siga o caminho completo: grupo -&gt; YAML -&gt; sync -&gt; checagem -&gt; regra contextual -&gt; tela.</p></section><section class=\"lesson\"><h2>Validação dos experimentos e limites dos trechos</h2><p>Antes dos exercícios, confira se <code>sync_permissions</code> remove associações ausentes do YAML. O trecho <code>group.permissions.add(perm)</code>, sozinho, demonstra apenas adição. Não presuma que editar o YAML revoga automaticamente o acesso.</p><p>Uma permissão pode vir de outro grupo ou de uma atribuição direta. Registre os grupos e as permissões efetivas do perfil de teste e confira-os após a sincronização. Teste também a URL direta, além do menu ou botão.</p><p>Depois de cada experimento, restaure o YAML e as associações alteradas, sincronize conforme o procedimento confirmado no checkout e teste novamente. Entregue um registro com perfil, estado inicial, alteração, camada responsável, resultado esperado, resultado observado e confirmação da restauração.</p><p>No manager, <code>count() == 1</code> testa uma contagem específica de grupos usando o codename. Não equivale, por si só, a <code>user.has_perm()</code>; examine o filtro por polo e a implementação completa.</p><p>No caso ENADE, acompanhe também <code>not obj.is_concluido()</code> na view e a alternativa <code>is_coordenador</code> no template. A lista de grupos é um recorte: confira todas as restrições por curso e campus.</p><p>No caso Documentos, o link e a condição são o recorte do roteiro. Examine o bloco completo, <code>urls_documentos</code> e as views de destino para verificar o acesso direto.</p><h3>Para consultar depois</h3><p>Use os caminhos e as referências desta unidade como índice de investigação no VSCode. Compare os merges indicados com o checkout de trabalho antes de concluir qual comportamento está vigente.</p></section>";
function module3(){return module3LessonHtml + code('view','Complemento: permissões na view turma()','Localize has_group_cached(), pode_realizar_procedimentos e a verificação antes da remoção de alunos.') + code('remover','Complemento: autorização no model','O método verifica pode_remover_da_turma() e pode_ser_excluido_do_diario() antes de alterar vínculos; nem todos os registros recebidos precisam ser removidos.');}
function modulePage(m){return `<div class="sectionhead"><span class="eyebrow">MÓDULO ${m.num} · ESTUDO GUIADO</span><h1>${m.name}</h1><p>${m.desc}</p><div class="bar"><div style="width:${modulePercent(m)}%"></div></div><span class="muted small">${moduleDone(m)}/${moduleTotal(m)} etapas concluídas</span></div><section class="panel"><h3>Ao terminar este módulo, você será capaz de:</h3><ul>${m.goals.map(g=>`<li>${g}</li>`).join('')}</ul></section>${m.id==='m1'?module1():m.id==='m2'?module2():module3()}${challengeArea(m.id)}${tasks(m)}${quiz(m)}${notesBlock(m.id)}<div class="panel"><h3>Continue seus estudos</h3><button class="btn" data-page="${m.id==='m1'?'m2':m.id==='m2'?'m3':'roadmap'}">${m.id==='m3'?'Ver próximos encontros':'Ir para o próximo módulo'} →</button></div>`}
const libraryItems=[['model','Model Turma: campos e managers'],['matriculados','Métodos de matrículas'],['horarios','Método get_horarios()'],['view','View turma() comentada'],['rtr','Decorator @rtr()'],['gettemplate','Localização automática do template'],['httprr','Redirecionamento com httprr()'],['pdfresponse','Resposta PDFResponse'],['remover','Método remover_alunos()']];
function library(){let key=state.library||'view';return `<div class="sectionhead"><span class="eyebrow">REFERÊNCIA DE CÓDIGO</span><h1>Biblioteca de códigos comentados</h1><p>Exemplos extraídos dos arquivos fornecidos. Use as referências para localizar a implementação no repositório.</p></div><div class="tabs">${libraryItems.map(([k,t])=>`<button data-library="${k}" class="${k===key?'selected':''}">${escape(t)}</button>`).join('')}</div>${code(key,libraryItems.find(x=>x[0]===key)[1],key==='view'?'Código da view com comentários didáticos.':'Trecho extraído do arquivo original anexado.') }<section class="panel"><h3>Como estudar um trecho</h3><p>Leia primeiro a assinatura da função, identifique os parâmetros, localize as chamadas a outros componentes e explique o retorno. Depois oculte os comentários e tente repetir a análise.</p></section>`}
function notes(){return `<div class="sectionhead"><span class="eyebrow">SEU CADERNO</span><h1>Minhas anotações</h1><p>As notas são salvas neste navegador e podem ser exportadas em Markdown.</p></div>${notesBlock('geral')}${course.map(m=>`<div class="panel"><h3>${m.name}</h3><p>${escape((state['note:'+m.id]||'').slice(0,350))||'Nenhuma anotação registrada.'}</p><button class="btn secondary" data-page="${m.id}">Abrir módulo →</button></div>`).join('')}`}
function progress(){return `<div class="sectionhead"><span class="eyebrow">ACOMPANHAMENTO</span><h1>Meu progresso</h1><p>Veja as atividades concluídas e retome os módulos que ainda deseja revisar.</p></div>${course.map(m=>`<section class="panel"><div class="codebar"><h3>${m.num} · ${m.name}</h3><strong>${modulePercent(m)}%</strong></div><div class="bar"><div style="width:${modulePercent(m)}%"></div></div><p class="muted">${moduleDone(m)} de ${moduleTotal(m)} atividades${moduleChallenges[m.id]?.length?` · ${challengeDone(m)} de ${moduleChallenges[m.id].length} chamados`:''}</p><button class="btn secondary" data-page="${m.id}">Revisar módulo →</button></section>`).join('')}<div class="panel"><p>O progresso fica armazenado apenas neste dispositivo e navegador.</p><button class="btn ghost" id="reset">Reiniciar atividades, chamados e respostas</button></div>`}
function roadmap(){return `<div class="sectionhead"><span class="eyebrow">TRILHA COMPLETA</span><h1>Próximos encontros</h1><p>O plano de curso prevê cinco encontros. Os três módulos introdutórios já estão disponíveis; os materiais detalhados dos demais encontros serão incorporados posteriormente.</p></div><div class="panel"><span class="tag">ENCONTRO 04 · PLANEJADO</span><h2>Debugging e investigação de chamados</h2><p>Tracebacks, logs, Django Shell, consultas ORM e análise de inconsistências entre entidades acadêmicas.</p><p><strong>Caso principal:</strong> pendências por Diretoria e relacionamentos acadêmicos.</p></div><div class="panel"><span class="tag">ENCONTRO 05 · PLANEJADO</span><h2>Implementação, testes e entrega</h2><p>Correções pequenas, testes de regressão, Git, revisão de código e validação das regras acadêmicas.</p><p><strong>Caso principal:</strong> regra de diário pendente, PCC e <code>nao_exige_nota</code>.</p></div><button class="btn" data-page="plan">Consultar plano de curso →</button>`}
function searchPage(q){let entries=[...course.map(m=>({id:m.id,title:m.name,content:m.desc+' '+m.goals.join(' ')+' '+m.tasks.join(' ')})),...libraryItems.map(([id,title])=>({id:'library',title,content:samples[id].code,lib:id}))];let found=entries.filter(e=>(e.title+' '+e.content).toLowerCase().includes(q.toLowerCase()));return `<div class="sectionhead"><span class="eyebrow">PESQUISA</span><h1>Resultados para “${escape(q)}”</h1><p>${found.length} resultados encontrados.</p></div>${found.map(e=>`<div class="result"><button ${e.lib?`data-open-library="${e.lib}"`:`data-page="${e.id}"`}>${escape(e.title)} →</button><p class="muted small">${escape(e.content.replace(/\s+/g,' ').slice(0,170))}...</p></div>`).join('')||'<div class="empty">Tente outro termo, como “Turma”, “rtr” ou “permissão”.</div>'}`}
let current='home';function navigate(page){current=page;location.hash=page;render();$('#sidebar').classList.remove('open');window.scrollTo(0,0)}function downloadText(name,txt){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/markdown;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function render(){let m=course.find(x=>x.id===current);$('#crumb').textContent='Guia do participante / '+(m?m.name:({home:'Início',plan:'Plano de curso',library:'Códigos comentados',notes:'Anotações',progress:'Progresso',roadmap:'Próximos encontros',search:'Pesquisa'}[current]||'Início'));$('#content').innerHTML=current==='home'?home():current==='plan'?plan():current==='library'?library():current==='notes'?notes():current==='progress'?progress():current==='roadmap'?roadmap():current==='search'?searchPage($('#search').value):m?modulePage(m):home();document.querySelectorAll('[data-page]').forEach(b=>{b.onclick=()=>navigate(b.dataset.page);b.classList.toggle('active',b.dataset.page===current)});document.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>{state.library=b.dataset.library;save();render()});document.querySelectorAll('[data-open-library]').forEach(b=>b.onclick=()=>{state.library=b.dataset.openLibrary;save();navigate('library')});document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{state['task:'+b.dataset.task]=b.checked;save();render()});document.querySelectorAll('[data-ticket]').forEach(b=>b.onchange=()=>{state['ticket:'+b.dataset.ticket]=b.checked;save();render()});document.querySelectorAll('[data-quiz]').forEach(b=>b.onchange=()=>{let [id,i,j]=b.dataset.quiz.split(':');state['quiz:'+id+':'+i]=+j;save();render()});document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{state['note:'+t.dataset.note]=t.value;save()});document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>downloadText('anotacoes_'+b.dataset.export+'.md','# Minhas anotações — SUAP EDU\n\n'+(state['note:'+b.dataset.export]||'')));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(samples[b.dataset.copy].code);b.textContent='Copiado ✓'}catch{b.textContent='Selecione e copie o trecho'}});document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{let el=$('#code-'+b.dataset.toggle);el.classList.toggle('no-comments');b.textContent=el.classList.contains('no-comments')?'Mostrar comentários':'Ocultar comentários'});if($('#reset'))$('#reset').onclick=()=>{if(confirm('Reiniciar atividades, chamados e respostas? As anotações serão preservadas.')){Object.keys(state).filter(k=>k.startsWith('task:')||k.startsWith('ticket:')||k.startsWith('quiz:')).forEach(k=>delete state[k]);save();render()}}}
$('#hamburger').onclick=()=>$('#sidebar').classList.toggle('open');$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('suapEduParticipanteTheme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('suapEduParticipanteTheme')==='dark')document.body.classList.add('dark');$('#print').onclick=()=>window.print();let timeout;$('#search').oninput=()=>{clearTimeout(timeout);timeout=setTimeout(()=>{if($('#search').value.trim()){current='search';render()}else navigate('home')},220)};window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(['home','plan','library','notes','progress','roadmap',...course.map(x=>x.id)].includes(p)&&p!==current){current=p;render()}});current=['home','plan','library','notes','progress','roadmap',...course.map(x=>x.id)].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();
